using namespace std;using ll=long long;const ll P=998244353;
struct DSU{vector<int>p;DSU(int n):p(n,-1){}int f(int x){return p[x]<0?x:p[x]=f(p[x]);}void join(int a,int b){a=f(a);b=f(b);if(a==b)return;if(p[a]>p[b])swap(a,b);p[a]+=p[b];p[b]=a;}};
void groups(vector<int>a){map<int,vector<int>>g;for(int i=0;i<(int)a.size();i++)g[a[i]].push_back(i);cout<<g.size()<<'\n';for(auto&[k,v]:g){cout<<v.size();for(int x:v)cout<<' '<<x;cout<<'\n';}}
struct Treap{struct N{int l=0,r=0,sz=1;unsigned pri;ll val=0,sum=0,sq=0,b=1,c=0;bool rev=false;};vector<N>t;unsigned state=12739823;Treap(int cap){t.reserve(cap);t.push_back(N());t[0].sz=0;}int sz(int x){return t[x].sz;}int make(ll v){state^=state<<13;state^=state>>17;state^=state<<5;N a;a.pri=state;a.val=a.sum=v;a.sq=v*v%P;t.push_back(a);return t.size()-1;}void pull(int v){auto&x=t[v];x.sz=1+sz(x.l)+sz(x.r);x.sum=(t[x.l].sum+x.val+t[x.r].sum)%P;x.sq=(t[x.l].sq+x.val*x.val+t[x.r].sq)%P;}void affine(int v,ll b,ll c){if(!v)return;auto&x=t[v];x.sq=(b*b%P*x.sq+2*b%P*c%P*x.sum+c*c%P*x.sz)%P;x.sum=(b*x.sum+c*x.sz)%P;x.val=(b*x.val+c)%P;x.b=b*x.b%P;x.c=(b*x.c+c)%P;}void reversev(int v){if(v)t[v].rev=!t[v].rev;}void push(int v){auto&x=t[v];if(x.rev){swap(x.l,x.r);reversev(x.l);reversev(x.r);x.rev=false;}if(x.b!=1||x.c){affine(x.l,x.b,x.c);affine(x.r,x.b,x.c);x.b=1;x.c=0;}}pair<int,int>split(int v,int k){if(!v)return{0,0};push(v);if(sz(t[v].l)>=k){auto[a,b]=split(t[v].l,k);t[v].l=b;pull(v);return{a,v};}auto[a,b]=split(t[v].r,k-sz(t[v].l)-1);t[v].r=a;pull(v);return{v,b};}int merge(int a,int b){if(!a||!b)return a?a:b;if(t[a].pri>t[b].pri){push(a);t[a].r=merge(t[a].r,b);pull(a);return a;}push(b);t[b].l=merge(a,t[b].l);pull(b);return b;}};
